  'module.title.m1': { englishText: 'Day 1: Company Foundation & BGCT Introduction', tamilText: 'நாள் 1: நிறுவன அடிப்படை மற்றும் BGCT அறிமுகம்', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1; Section 3, Day 1' },
  'module.summary.m1': { englishText: 'What Digitweb Lanka does, what BGCT stands for, and the core company rule that the handbook is the only source of company knowledge.', tamilText: 'Digitweb Lanka என்ன செய்கிறது, BGCT என்றால் என்ன, மற்றும் கையேடு மட்டுமே நிறுவன அறிவின் ஒரே ஆதாரம் என்ற முக்கிய நிறுவனக் கொள்கை.', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1; Section 3, Day 1' },
  'module.realWorldPace.m1': { englishText: '1 working day (Day 1 of the 7-day evaluation)', tamilText: '1 பணி நாள் (7-நாள் மதிப்பீட்டின் நாள் 1)', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1; Section 3, Day 1' },
  'lesson.title.m1-l1': { englishText: 'What This Guide Is', tamilText: 'இந்த வழிகாட்டி என்னவென்பது', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1, points 1–2; Field table' },
  'lesson.paragraph.m1-l1': { englishText: 'This guide tells you exactly what to do from Day 1 of your evaluation. Follow it in order — do not skip sections. You have a 7-day evaluation period, and it is unpaid: this is your opportunity to show you are right for Digitweb, and to decide if Digitweb is right for you. Your trainer for the entire evaluation and probation period is Claude, an AI assistant loaded with Digitweb’s BGCT knowledge base for your role.', tamilText: 'இந்த வழிகாட்டி உங்கள் மதிப்பீட்டின் 1வது நாளிலிருந்து சரியாக என்ன செய்ய வேண்டும் என்பதை கூறுகிறது. வரிசைப்படி பின்பற்றவும் — பிரிவுகளைத் தவிர்க்க வேண்டாம். உங்களுக்கு 7-நாள் மதிப்பீட்டுக் காலம் உள்ளது, அது ஊதியம் இல்லாதது: இது நீங்கள் Digitweb-க்கு பொருத்தமானவர் என்பதைக் காட்டவும், Digitweb உங்களுக்குப் பொருத்தமானதா என்பதை முடிவு செய்யவும் கிடைக்கும் வாய்ப்பாகும். உங்கள் மதிப்பீடு மற்றும் probation காலம் முழுவதும் உங்கள் பயிற்றுநர் Claude ஆவார் — இது உங்கள் பணிக்கான Digitweb-இன் BGCT அறிவுத் தளத்துடன் இயங்கும் AI உதவியாளர்.', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1, points 1–2; Field table' },
  'lesson.title.m1-l2': { englishText: 'What is BGCT?', tamilText: 'BGCT என்றால் என்ன?', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1, "What is BGCT?" table' },
  'lesson.paragraph.m1-l2': { englishText: 'BGCT is Digitweb’s operating standard — every task at the company is documented in this format, and it is not optional reading. B is Best Practice: the standard the company expects you to reach. G is Guidance: the step-by-step roadmap showing how to reach that standard safely. C is Checklist: the control gate — binary YES/NO checks to confirm nothing is missed. T is Tutorial: the full written handbook, your source of truth for every task.', tamilText: 'BGCT என்பது Digitweb-இன் இயக்கத் தரநிலை — நிறுவனத்தில் உள்ள ஒவ்வொரு பணியும் இந்த வடிவத்தில் ஆவணப்படுத்தப்படுகிறது, இது விருப்பமான வாசிப்பு அல்ல. B என்பது சிறந்த நடைமுறை (Best Practice): நிறுவனம் நீங்கள் அடைய வேண்டும் என எதிர்பார்க்கும் தரநிலை. G என்பது வழிகாட்டுதல் (Guidance): அந்த தரநிலையை பாதுகாப்பாக அடைவது எப்படி என்பதைக் காட்டும் படிப்படியான வழிமுறை. C என்பது சரிபார்ப்புப் பட்டியல் (Checklist): கட்டுப்பாட்டு வாயில் — எதுவும் தவறவிடப்படவில்லை என்பதை உறுதிசெய்யும் ஆம்/இல்லை சரிபார்ப்புகள். T என்பது கையேடு (Tutorial): முழுமையான எழுதப்பட்ட கையேடு, ஒவ்வொரு பணிக்கும் உங்கள் உண்மையான ஆதாரம்.', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1, "What is BGCT?" table' },
  'lesson.title.m1-l3': { englishText: 'The Core Company Rule', tamilText: 'முக்கிய நிறுவனக் கொள்கை', status: S, sourceReference: 'Onboarding Guide v1.0 — Section 1, "The Core Company Rule"' },
